add("python", [
    dict(title="Explain Python memory management", cat="Python", one="CPython uses a heap, reference counts, and a garbage collector for cycles.",
         simple="When nothing points to an object, refcount hits 0 and it is freed. Cycles need the cyclic GC.\nDo not load huge files as giant Python object graphs.",
         why="5-year Python.", say="Refcount plus cyclic GC. Stream large data."),
    dict(title="What is the GIL?", cat="Python", one="Only one thread runs Python bytecode at a time in CPython.",
         simple="Threads help waiting on APIs. They do not speed tight Python CPU loops. Use processes, Polars, or numpy for CPU.",
         why="Classic.", say="GIL: I/O threads yes, CPU threads no."),
    dict(title="Threading vs multiprocessing?", cat="Python", one="Threads share memory (I/O). Processes isolate memory (CPU).",
         simple="Many LLM HTTP calls: threads or async. Heavy CPU on files: processes.",
         why="Parallelism.", say="I/O → threads/async. CPU → processes or native libs."),
    dict(title="Asyncio vs threading?", cat="Python", one="Async is cooperative on one thread. Threads fit blocking SDKs.",
         simple="If the SDK is sync, a thread pool is honest. If you own HTTP, asyncio scales well.",
         why="Agents call many APIs.", say="I match async to an async stack. I do not force async on a sync SDK."),
    dict(title="What are generators?", cat="Python", one="yield produces values lazily.",
         simple="You can walk a file line by line without a giant list.",
         why="Big files.", say="Generators stream values."),
    dict(title="Why use generators for large files?", cat="Python", one="Constant memory vs loading everything.",
         simple="chunksize in pandas or Polars scan is the same idea.",
         why="Production.", say="Stream. Never read the whole CSV into RAM."),
    dict(title="Iterator vs iterable?", cat="Python", one="Iterable can be looped. Iterator is the walker with next().",
         simple="A list is iterable. iter(list) is an iterator. A generator is an iterator.",
         why="Language.", say="Iterable: for-loop source. Iterator: the pointer."),
    dict(title="What are decorators?", cat="Python", one="Wrappers that add retry, logs, or timing.",
         simple="@retry(3) above a function.",
         why="Coding round.", say="I decorate retries and metrics.",
         code="def retry(n):\n    def deco(fn):\n        def inner(*a,**k):\n            last=None\n            for _ in range(n):\n                try: return fn(*a,**k)\n                except Exception as e: last=e\n            raise last\n        return inner\n    return deco"),
    dict(title="What are context managers?", cat="Python", one="with blocks that always clean up.",
         simple="Files, DB sessions, locks, tracing spans.",
         why="Leaks.", say="I use with for every connection and file."),
    dict(title="Shallow copy vs deep copy?", cat="Python", one="Shallow shares nested objects. Deep copies the tree.",
         simple="Copying state dicts in an agent: watch nested lists.",
         why="Bugs.", say="Shallow by default. deepcopy when nested mutation matters."),
    dict(title="Mutable vs immutable?", cat="Python", one="list/dict change in place. str/tuple/int do not.",
         simple="Never def f(x=[]). Use None.",
         why="Footgun.", say="No mutable defaults. Immutable dict keys."),
    dict(title="__init__ vs __new__?", cat="Python", one="__new__ creates. __init__ fills. You usually write __init__.",
         simple="__new__ is rare: immutables, some factories.",
         why="OOP.", say="I live in __init__ unless I have a special constructor."),
    dict(title="@staticmethod vs @classmethod?", cat="Python", one="static has no cls/self. classmethod gets cls for alternate constructors.",
         simple="from_json(cls, data) is a classmethod.",
         why="API.", say="classmethod for factories. staticmethod for namespaced helpers."),
    dict(title="Abstract class vs Protocol?", cat="Python", one="ABC enforces methods at runtime. Protocol is typing/duck typing. No Java interface keyword.",
         simple="ModelClient(Protocol) is enough for adapters.",
         why="Modular LLM.", say="Protocol or ABC for the model port."),
    dict(title="Composition vs inheritance?", cat="Python", one="Prefer has-a. Assistant has a ModelClient. GeminiClient is-a ModelClient.",
         simple="Deep inheritance trees get brittle.",
         why="SOLID.", say="Compose tools and models. Inherit only for real subtypes."),
    dict(title="What are dataclasses?", cat="Python", one="Auto init/repr for field classes. Good DTOs and state.",
         simple="@dataclass class StockRow: item: str; qty: int",
         why="Clean code.", say="Dataclass or Pydantic for tool payloads."),
    dict(title="What is dependency injection?", cat="Python", one="Pass dependencies in. Do not construct them inside.",
         simple="Tests inject FakeModel.",
         why="Testable.", say="Constructor injection of interfaces."),
    dict(title="How do you structure a production Python project?", cat="Python", one="Use cases in the middle, adapters at the edge, tests, env config, thin entrypoint.",
         simple="api / domain / adapters / tests.",
         why="5-year.", say="I keep vendor SDKs in adapters, not in routes."),
    dict(title="How do you handle exceptions?", cat="Python", one="Catch specific types, chain with from, do not swallow.",
         simple="Turn HTTPError into CatalogDown.",
         why="Ops.", say="No bare except. Map to domain errors."),
    dict(title="How do you write testable Python?", cat="Python", one="Pure functions for matching/math. Fake the LLM. No network in unit tests.",
         simple="Validator tests use a dict of tool output.",
         why="Quality.", say="I unit-test matchers and validators without API keys."),
    dict(title="Find duplicates in a list", cat="Python coding", time="3–5 minutes", one="Walk once with a seen set.",
         simple="O(n) time.", say="Set of seen ids.",
         code="def dups(xs):\n    s,d=set(),set()\n    for x in xs:\n        (d if x in s else s).add(x)\n    return list(d)"),
    dict(title="First non-repeating character", cat="Python coding", time="3–5 minutes", one="Count, then first with count 1.",
         simple="Two passes with Counter.", say="Counter then scan.",
         code="from collections import Counter\ndef first_uniq(s):\n    c=Counter(s)\n    for ch in s:\n        if c[ch]==1: return ch"),
    dict(title="Implement an LRU cache", cat="Python coding", time="8–10 minutes", one="OrderedDict: move to end on get/put, pop from the other end when full.",
         simple="O(1) get/put. Used to cache LLM answers.", say="OrderedDict LRU.",
         code="from collections import OrderedDict\nclass LRU:\n    def __init__(s,n): s.n,s.d=n,OrderedDict()\n    def get(s,k):\n        if k not in s.d: return None\n        s.d.move_to_end(k); return s.d[k]\n    def put(s,k,v):\n        s.d[k]=v; s.d.move_to_end(k)\n        if len(s.d)>s.n: s.d.popitem(last=False)"),
    dict(title="Process a huge file without loading it", cat="Python coding", time="4–6 minutes", one="Iterate lines or chunks. Write as you go.",
         simple="for line in f / scan_csv.", say="Stream, do not f.read().",
         code="with open('orders.csv') as f:\n    next(f)\n    for line in f:\n        yield parse(line)"),
    dict(title="Write a retry decorator", cat="Python coding", time="5–7 minutes", one="Loop n times. Retry timeouts/429 only. Backoff.",
         simple="Do not retry bad JSON 400s.", say="Attempts + retryable exceptions + sleep."),
    dict(title="Implement a rate limiter", cat="Python coding", time="6–8 minutes", one="Sliding window deque per user, or token bucket. Redis if many servers.",
         simple="10 calls / 60 seconds.", say="In-process deque; Redis for a cluster.",
         code="from collections import deque,defaultdict\nimport time\nW=defaultdict(deque)\ndef allow(u,n=10,span=60):\n    now=time.time(); q=W[u]\n    while q and now-q[0]>span: q.popleft()\n    if len(q)>=n: return False\n    q.append(now); return True"),
    dict(title="Merge two large datasets efficiently", cat="Python coding", time="5–7 minutes", one="Join in SQL/Polars. Not nested Python loops.",
         simple="a.join(b, on='order_id').", say="Engine join, not O(n*m)."),
    dict(title="Group transactions by account", cat="Python coding", time="4–6 minutes", one="GROUP BY in SQL, or group_by in Polars. defaultdict only for small data.",
         simple="Do not group 80M rows in a Python dict of lists.", say="Group in the database or Polars."),
    dict(title="Find duplicate orders", cat="Python coding", time="4–6 minutes", one="GROUP BY key HAVING COUNT(*)>1.",
         simple="Business key first.", say="SQL having count > 1."),
    dict(title="Find mismatched records between two datasets", cat="Python coding", time="5–7 minutes", one="Full join on the key. Nulls and differing fields are breaks.",
         simple="Same as priority Q9.", say="Join. Four buckets. No LLM matching."),
])

add("etl", [
    dict(title="What is ETL?", cat="ETL", one="Extract, Transform, Load.",
         simple="Pull a file, clean it, save it.", why="Baseline.", say="Move and clean data with checks."),
    dict(title="ETL vs ELT?", cat="ETL", one="ETL cleans first. ELT loads raw then transforms in the warehouse.",
         simple="dbt is often ELT. Still land the raw file.", why="Modern stack.", say="I land raw, then ELT if the warehouse is the brain."),
    dict(title="Batch vs streaming?", cat="ETL", one="Batch is a nightly file. Streaming is continuous events.",
         simple="One 19:00 CSV is batch. Do not start with Kafka.", why="Overkill check.", say="Batch for nightly files. Stream only if data arrives all day."),
    dict(title="How do you design a data pipeline?", cat="ETL", one="Land, validate, transform, load, observe. Idempotent.",
         simple="Draw stages before picking Spark.", why="Open design.", say="Stages + failure policy + job_id."),
    dict(title="What happens when 1% of records are invalid?", cat="ETL", one="Quarantine 1%, load 99%, alert if that is a spike.",
         simple="Do not fail the night for dirty item codes if the file is otherwise good.", why="Judgment.", say="Reject table + threshold alert."),
    dict(title="How do you handle duplicate records?", cat="ETL", one="Define the key. Keep last, or fail if duplicates are illegal.",
         simple="unique(order_id, keep='last').", why="Double count.", say="Key plus an explicit keep rule."),
    dict(title="What is a dead-letter queue?", cat="ETL", one="Storage for failed rows/messages so they can be replayed.",
         simple="orders_reject is a DLQ for files.", why="No silent drop.", say="Failed work goes to DLQ with a reason."),
    dict(title="What is incremental processing?", cat="ETL", one="Only new/changed data since the last success.",
         simple="Watermark on last timestamp.", why="Cost.", say="Store a watermark. Full reload only to rebuild."),
    dict(title="Full load vs incremental load?", cat="ETL", one="Full replaces a set. Incremental applies a delta. Replacing one date partition is a good middle.",
         simple="Nightly file: replace that date.", why="Trade-off.", say="I replace the day. Incremental for CDC."),
    dict(title="How do you handle schema changes?", cat="ETL", one="Header contracts. New columns to extra_json. Missing required columns fail the file.",
         simple="coupon_code added: keep going. order_id missing: stop.", why="Sources drift.", say="Compatible adds vs breaking fails."),
    dict(title="How do you handle missing values?", cat="ETL", one="Required reject. Optional null. Never invent a price.",
         simple="Missing comment OK.", why="No guessing.", say="Blocking fields vs optional flags."),
    dict(title="How do you monitor a data pipeline?", cat="ETL", one="Freshness, duration, counts, reject %, totals, last success.",
         simple="File late at 19:30 → page.", why="Ops.", say="Alert on delay and count drift."),
    dict(title="What metrics would you track?", cat="ETL", one="In/out rows, bytes, time, memory, reject reasons, money vs control.",
         simple="One board per job.", why="Be specific.", say="Counts, money, time, reasons."),
    dict(title="Pandas vs Polars vs Spark?", cat="ETL", one="Pandas samples. Polars one big file. Spark cluster-scale joins.",
         simple="20 GB: Polars. 200 GB joins: Spark.", why="Choice.", say="Right tool for size, not a brand."),
])

